import React, { useState, useEffect, useRef } from 'react';
import { useTheme } from '../../context/ThemeContext';
import { PlusIcon } from "../../icons";
import { popularAssets } from '../../data/popularAssets';

const WatchList = () => {
    const { theme } = useTheme();
    const container = useRef();
    const dropdownRef = useRef();
    // Default symbols cleared as per user request
    const [symbols, setSymbols] = useState([]);
    const [searchTerm, setSearchTerm] = useState("");
    const [recommendations, setRecommendations] = useState([]);
    const [showDropdown, setShowDropdown] = useState(false);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setShowDropdown(false);
            }
        };

        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, []);

    useEffect(() => {
        if (searchTerm.trim()) {
            const filtered = popularAssets.filter(asset =>
                asset.symbol.toLowerCase().includes(searchTerm.toLowerCase()) ||
                asset.description.toLowerCase().includes(searchTerm.toLowerCase())
            );
            setRecommendations(filtered);
            setShowDropdown(true);
        } else {
            setRecommendations([]);
            setShowDropdown(false);
        }
    }, [searchTerm]);

    const addSymbol = (symbol) => {
        if (!symbols.includes(symbol)) {
            setSymbols([...symbols, symbol]);
        }
        setSearchTerm("");
        setShowDropdown(false);
    };

    const removeSymbol = (symbolToRemove) => {
        setSymbols(symbols.filter(s => s !== symbolToRemove));
    };

    useEffect(() => {
        if (container.current) {
            container.current.innerHTML = "";
            const script = document.createElement("script");
            script.src = "https://s3.tradingview.com/external-embedding/embed-widget-market-quotes.js";
            script.async = true;
            script.innerHTML = JSON.stringify({
                "width": "100%",
                "height": "100%",
                "symbolsGroups": [
                    {
                        "name": "My Watchlist",
                        "originalName": "My Watchlist",
                        "symbols": symbols.length > 0 ? symbols.map(s => ({ "name": s })) : []
                    }
                ],
                "showSymbolLogo": true,
                "isTransparent": true,
                "colorTheme": theme,
                "locale": "en"
            });
            container.current.appendChild(script);
        }
    }, [symbols, theme]);

    return (
        <div className="rounded-2xl border border-gray-200 bg-white p-5 dark:border-gray-800 dark:bg-white/[0.03] md:p-6 h-full flex flex-col relative w-full">
            <div className="flex flex-col gap-4 mb-4 relative z-50">
                <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                    <h3 className="text-lg font-semibold text-gray-800 dark:text-white/90">
                        My Watchlist
                    </h3>

                    <div className="relative w-full sm:w-64" ref={dropdownRef}>
                        <div className="flex items-center gap-2 w-full">
                            <input
                                type="text"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                onFocus={() => { if (searchTerm) setShowDropdown(true) }}
                                placeholder="Search Symbol (e.g. SUZLON)"
                                className="px-4 py-2 text-sm border border-gray-200 rounded-lg dark:border-gray-700 dark:bg-gray-800 dark:text-gray-300 focus:outline-none focus:border-brand-500 w-full"
                            />
                            <button
                                onClick={() => addSymbol(searchTerm.toUpperCase())} // Allow manual add if not in list
                                className="p-2 text-white bg-brand-500 rounded-lg hover:bg-brand-600 focus:outline-none flex-shrink-0"
                            >
                                <PlusIcon className="size-5" />
                            </button>
                        </div>

                        {/* Dropdown Menu */}
                        {showDropdown && recommendations.length > 0 && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-xl max-h-60 overflow-y-auto z-[100]">
                                {recommendations.map((asset) => (
                                    <button
                                        key={asset.symbol}
                                        onClick={() => addSymbol(asset.symbol)}
                                        className="w-full text-left px-4 py-2 text-sm hover:bg-gray-50 dark:hover:bg-gray-700 flex items-center justify-between group"
                                    >
                                        <span className="font-semibold text-gray-800 dark:text-white">
                                            {asset.symbol.split(':')[1] || asset.symbol}
                                        </span>
                                        <span className="text-xs text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-300">
                                            {asset.description}
                                        </span>
                                        <span className="text-[10px] text-gray-400 dark:text-gray-500 ml-2">
                                            {asset.symbol.split(':')[0]}
                                        </span>
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {/* Active Watchlist Tags */}
                {symbols.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                        {symbols.map((symbol) => (
                            <div key={symbol} className="group relative px-3 py-1 bg-gray-100 dark:bg-gray-800 rounded-full text-xs font-medium text-gray-700 dark:text-gray-300 border border-transparent hover:border-gray-300 dark:hover:border-gray-600 transition-all cursor-default">
                                {symbol.split(':')[1] || symbol}
                                <button
                                    onClick={() => removeSymbol(symbol)}
                                    className="absolute -top-1 -right-1 bg-red-500 text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity shadow-sm hover:bg-red-600"
                                    title="Remove from watchlist"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor">
                                        <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                                    </svg>
                                </button>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="flex-1 overflow-hidden min-h-[400px]" ref={container}>
                <div className="tradingview-widget-container">
                    <div className="tradingview-widget-container__widget"></div>
                </div>
            </div>
        </div>
    );
};

export default WatchList;

import React, { useState } from 'react';
import axiosInstance from "../../utils/axiosInstance";
import { API_PATHS } from "../../utils/apipaths";

import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

const AiRecommendation = () => {
    const [formData, setFormData] = useState({
        age: '',
        employmentStatus: 'Employed',
        annualIncome: '',
        monthlySavings: '',
        investmentGoal: 'Retirement',
        timeHorizon: 'Short Term (1-3 years)',
        riskTolerance: 'Medium',
    });

    const [recommendation, setRecommendation] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        setRecommendation('');

        try {
            const response = await axiosInstance.post(API_PATHS.AI.RECOMMEND, formData);
            setRecommendation(response.data.recommendation);
        } catch (err) {
            console.error(err);
            const detailedError = err.response?.data?.message || err.response?.data?.error || 'Failed to get recommendation';
            setError(detailedError);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div>
            <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">AI Investment Advisor</h1>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Form Section */}
                <div className="lg:col-span-1 rounded-2xl border border-gray-200 bg-white px-5 pt-5 pb-5 dark:border-gray-800 dark:bg-white/[0.03] sm:px-6 sm:pt-6">
                    <div className="border-b border-gray-200 py-4 mb-4 dark:border-gray-800">
                        <h3 className="font-medium text-lg text-gray-800 dark:text-white/90">
                            Your Profile
                        </h3>
                    </div>
                    <form onSubmit={handleSubmit}>
                        {/* Age */}
                        <div className="mb-4">
                            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-400">
                                Age
                            </label>
                            <input
                                type="number"
                                name="age"
                                value={formData.age}
                                onChange={handleChange}
                                placeholder="Enter your age"
                                required
                                className="w-full rounded-lg border border-gray-300 bg-transparent py-3 px-4 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 transition dark:border-gray-700 dark:bg-gray-800 dark:text-white dark:focus:border-blue-500"
                            />
                        </div>

                        {/* Employment Status */}
                        <div className="mb-4">
                            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-400">
                                Employment Status
                            </label>
                            <div className="relative z-20">
                                <select
                                    name="employmentStatus"
                                    value={formData.employmentStatus}
                                    onChange={handleChange}
                                    className="w-full appearance-none rounded-lg border border-gray-300 bg-transparent py-3 px-4 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 transition dark:border-gray-700 dark:bg-gray-800 dark:text-white dark:focus:border-blue-500"
                                >
                                    <option value="Employed">Employed</option>
                                    <option value="Self-Employed">Self-Employed</option>
                                    <option value="Student">Student</option>
                                    <option value="Retired">Retired</option>
                                    <option value="Unemployed">Unemployed</option>
                                </select>
                                <span className="absolute right-4 top-1/2 z-10 -translate-y-1/2 text-gray-400">
                                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                        <g opacity="0.8">
                                            <path fillRule="evenodd" clipRule="evenodd" d="M5.29289 8.29289C5.68342 7.90237 6.31658 7.90237 6.70711 8.29289L12 13.5858L17.2929 8.29289C17.6834 7.90237 18.3166 7.90237 18.7071 8.29289C19.0976 8.68342 19.0976 9.31658 18.7071 9.70711L12.7071 15.7071C12.3166 16.0976 11.6834 16.0976 11.2929 15.7071L5.29289 9.70711C4.90237 9.31658 4.90237 8.68342 5.29289 8.29289Z" fill="currentColor"></path>
                                        </g>
                                    </svg>
                                </span>
                            </div>
                        </div>

                        {/* Annual Income */}
                        <div className="mb-4">
                            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-400">
                                Annual Income (₹)
                            </label>
                            <input
                                type="number"
                                name="annualIncome"
                                value={formData.annualIncome}
                                onChange={handleChange}
                                placeholder="e.g. 500000"
                                required
                                className="w-full rounded-lg border border-gray-300 bg-transparent py-3 px-4 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 transition dark:border-gray-700 dark:bg-gray-800 dark:text-white dark:focus:border-blue-500"
                            />
                        </div>

                        {/* Monthly Savings */}
                        <div className="mb-4">
                            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-400">
                                Monthly Investment Capacity (₹)
                            </label>
                            <input
                                type="number"
                                name="monthlySavings"
                                value={formData.monthlySavings}
                                onChange={handleChange}
                                placeholder="e.g. 5000"
                                required
                                className="w-full rounded-lg border border-gray-300 bg-transparent py-3 px-4 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 transition dark:border-gray-700 dark:bg-gray-800 dark:text-white dark:focus:border-blue-500"
                            />
                        </div>

                        {/* Goal */}
                        <div className="mb-4">
                            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-400">
                                Investment Goal
                            </label>
                            <div className="relative z-20">
                                <select
                                    name="investmentGoal"
                                    value={formData.investmentGoal}
                                    onChange={handleChange}
                                    className="w-full appearance-none rounded-lg border border-gray-300 bg-transparent py-3 px-4 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 transition dark:border-gray-700 dark:bg-gray-800 dark:text-white dark:focus:border-blue-500"
                                >
                                    <option value="Retirement">Retirement</option>
                                    <option value="Buying a House">Buying a House</option>
                                    <option value="Education">Education</option>
                                    <option value="Wealth Creation">Wealth Creation</option>
                                    <option value="Emergency Fund">Emergency Fund</option>
                                </select>
                                <span className="absolute right-4 top-1/2 z-10 -translate-y-1/2 text-gray-400">
                                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                        <g opacity="0.8">
                                            <path fillRule="evenodd" clipRule="evenodd" d="M5.29289 8.29289C5.68342 7.90237 6.31658 7.90237 6.70711 8.29289L12 13.5858L17.2929 8.29289C17.6834 7.90237 18.3166 7.90237 18.7071 8.29289C19.0976 8.68342 19.0976 9.31658 18.7071 9.70711L12.7071 15.7071C12.3166 16.0976 11.6834 16.0976 11.2929 15.7071L5.29289 9.70711C4.90237 9.31658 4.90237 8.68342 5.29289 8.29289Z" fill="currentColor"></path>
                                        </g>
                                    </svg>
                                </span>
                            </div>
                        </div>

                        {/* Time Horizon */}
                        <div className="mb-4">
                            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-400">
                                Time Horizon
                            </label>
                            <div className="relative z-20">
                                <select
                                    name="timeHorizon"
                                    value={formData.timeHorizon}
                                    onChange={handleChange}
                                    className="w-full appearance-none rounded-lg border border-gray-300 bg-transparent py-3 px-4 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 transition dark:border-gray-700 dark:bg-gray-800 dark:text-white dark:focus:border-blue-500"
                                >
                                    <option value="Short Term (1-3 years)">Short Term (1-3 years)</option>
                                    <option value="Medium Term (3-7 years)">Medium Term (3-7 years)</option>
                                    <option value="Long Term (7+ years)">Long Term (7+ years)</option>
                                </select>
                                <span className="absolute right-4 top-1/2 z-10 -translate-y-1/2 text-gray-400">
                                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                        <g opacity="0.8">
                                            <path fillRule="evenodd" clipRule="evenodd" d="M5.29289 8.29289C5.68342 7.90237 6.31658 7.90237 6.70711 8.29289L12 13.5858L17.2929 8.29289C17.6834 7.90237 18.3166 7.90237 18.7071 8.29289C19.0976 8.68342 19.0976 9.31658 18.7071 9.70711L12.7071 15.7071C12.3166 16.0976 11.6834 16.0976 11.2929 15.7071L5.29289 9.70711C4.90237 9.31658 4.90237 8.68342 5.29289 8.29289Z" fill="currentColor"></path>
                                        </g>
                                    </svg>
                                </span>
                            </div>
                        </div>

                        {/* Risk Tolerance */}
                        <div className="mb-6">
                            <label className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-400">
                                Risk Tolerance
                            </label>
                            <div className="relative z-20">
                                <select
                                    name="riskTolerance"
                                    value={formData.riskTolerance}
                                    onChange={handleChange}
                                    className="w-full appearance-none rounded-lg border border-gray-300 bg-transparent py-3 px-4 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 transition dark:border-gray-700 dark:bg-gray-800 dark:text-white dark:focus:border-blue-500"
                                >
                                    <option value="Low">Low (Conservative)</option>
                                    <option value="Medium">Medium (Balanced)</option>
                                    <option value="High">High (Aggressive)</option>
                                </select>
                                <span className="absolute right-4 top-1/2 z-10 -translate-y-1/2 text-gray-400">
                                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                        <g opacity="0.8">
                                            <path fillRule="evenodd" clipRule="evenodd" d="M5.29289 8.29289C5.68342 7.90237 6.31658 7.90237 6.70711 8.29289L12 13.5858L17.2929 8.29289C17.6834 7.90237 18.3166 7.90237 18.7071 8.29289C19.0976 8.68342 19.0976 9.31658 18.7071 9.70711L12.7071 15.7071C12.3166 16.0976 11.6834 16.0976 11.2929 15.7071L5.29289 9.70711C4.90237 9.31658 4.90237 8.68342 5.29289 8.29289Z" fill="currentColor"></path>
                                        </g>
                                    </svg>
                                </span>
                            </div>
                        </div>

                        <button className="flex w-full justify-center rounded-lg bg-blue-600 p-3 font-medium text-white hover:bg-blue-700 transition">
                            {loading ? 'Analyzing...' : 'Get Recommendation'}
                        </button>

                        {error && (
                            <div className="mt-4 p-4 text-sm text-red-800 rounded-lg bg-red-50 dark:bg-red-900/10 dark:text-red-400 border border-red-100 dark:border-red-900/20" role="alert">
                                {error}
                            </div>
                        )}
                    </form>
                </div>

                {/* Result Section */}
                <div className="lg:col-span-2 rounded-2xl border border-gray-200 bg-white px-5 pt-5 pb-5 dark:border-gray-800 dark:bg-white/[0.03] sm:px-6 sm:pt-6">
                    <div className="border-b border-gray-200 py-4 mb-4 dark:border-gray-800">
                        <h3 className="font-medium text-lg text-gray-800 dark:text-white/90">
                            AI Recommendation
                        </h3>
                    </div>
                    <div className="min-h-[400px]">
                        {loading ? (
                            <div className="flex h-full flex-col items-center justify-center space-y-4">
                                <div className="h-16 w-16 animate-spin rounded-full border-4 border-solid border-blue-600 border-t-transparent"></div>
                                <p className="text-lg text-gray-500 dark:text-gray-400">Analyzing your profile...</p>
                            </div>
                        ) : recommendation ? (
                            <div className="prose dark:prose-invert max-w-none text-gray-800 dark:text-gray-200">
                                <ReactMarkdown
                                    remarkPlugins={[remarkGfm]}
                                    components={{
                                        table: ({ node, ...props }) => <table className="w-full text-left border-collapse my-4" {...props} />,
                                        thead: ({ node, ...props }) => <thead className="bg-gray-100 dark:bg-gray-800" {...props} />,
                                        th: ({ node, ...props }) => <th className="border border-gray-200 dark:border-gray-700 p-2 font-semibold" {...props} />,
                                        td: ({ node, ...props }) => <td className="border border-gray-200 dark:border-gray-700 p-2" {...props} />,
                                        h1: ({ node, ...props }) => <h1 className="text-2xl font-bold my-4" {...props} />,
                                        h2: ({ node, ...props }) => <h2 className="text-xl font-bold my-3" {...props} />,
                                        h3: ({ node, ...props }) => <h3 className="text-lg font-bold my-2" {...props} />,
                                        ul: ({ node, ...props }) => <ul className="list-disc pl-5 my-2" {...props} />,
                                        ol: ({ node, ...props }) => <ol className="list-decimal pl-5 my-2" {...props} />,
                                        li: ({ node, ...props }) => <li className="mb-1" {...props} />,
                                        p: ({ node, ...props }) => <p className="mb-3 leading-relaxed" {...props} />,
                                        strong: ({ node, ...props }) => <strong className="font-bold text-blue-600 dark:text-blue-400" {...props} />,
                                    }}
                                >
                                    {recommendation}
                                </ReactMarkdown>
                            </div>
                        ) : (
                            <div className="flex h-full items-center justify-center text-gray-500 dark:text-gray-400">
                                <p>Fill out the form and click "Get Recommendation" to see AI insights.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AiRecommendation;
